 882	\begin{lemma}\label{lem:qld-xz-lines}
 883	  There exists a function $\delta_P(\eps,m,d,q) = \poly(\eps,
 884	  md/q)$ such that the following holds. For $\mH \in \{\mH_\alice,\mH_\bob\}$ and for every pair of lines $\line_X$ and $\line_Z$ there exists a POVM $\{T^{\line_X, \line_Z}_{f_X, f_Z}\}$ acting on
 885	  $\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ with answers
 886	  consisting of pairs of polynomials $f_X, f_Z$ in $\deg_{md}(\line_X)
 887	  \times \deg_{md}(\line_Z)$
 888	  such that on average over pairs $(\line_X, x)$ and $(\line_Z, z)$
 889	  independently sampled from the line-point distribution,
 890	  \begin{align*}
 891	    (T^{\line_X, \line_Z}_{[ \eval_x(\cdot) =a, \eval_z(\cdot) = b]})_{\alice \alice'} &\simeq_{\delta_P} (\hat{Q}^{x,z}_{a, b})_{\bob \alice''}, \\
 892	\end{align*}
 893	  as well as all symmetric equivalents of this approximation. Moreover, if $\line_W$ is axis-parallel, then $f_W \in \deg_{d}(\line_W)$.
 894	\end{lemma}
